import { writeFileSync } from 'node:fs';
import { editorThemeTokens, themeCssVariables } from '../src/shared/styles/theme-tokens.ts';

const header = '/* Generated by scripts/generate-theme-css.mjs — do not edit by hand.\n   Source of truth: src/shared/styles/theme-tokens.ts */\n';
const rules = Object.keys(editorThemeTokens).map(theme =>
    `:root[data-editor-theme='${theme}'] {\n${themeCssVariables(theme)}\n}`,
);
writeFileSync(new URL('../src/shared/styles/theme.css', import.meta.url), `${header}\n${rules.join('\n\n')}\n`);
